    <div style="background:#3e2723;padding:20px;border-radius:12px;border:1px solid #64b5f6;margin-bottom:20px;">
    <h3 style="color:#e3f2fd;margin-top:0;">🧠 Lesson Summary</h3>
    <p>The scientific theory explains that humans evolved gradually over millions of years. Evidence includes fossils, footprints, stone tools, remains of fire and genes. Important sites include Rusinga, Fort Ternan, Koobi Fora, Nariokotome and Olorgesailie in Kenya, Olduvai and Laetoli in Tanzania, Hadar in Ethiopia and Sterkfontein in South Africa. Sites are preserved by museums and the law.</p>
    <h4 style="color:#e3f2fd;margin:16px 0 6px 0;">🗒️ Revision notes</h4>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Theory.</li>
    <li>Evidence.</li>
    <li>Sites.</li>
    <li>Preservation.</li>
    </ul>
    </div>
